
.panel {
  margin-top: 9px;
  padding: 8px 10px 9px;
  background: var(--c-surface-raised);
  border: 1px dashed var(--c-border);
  border-radius: 7px;
}

.panel__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
}

.panel__label {
  color: var(--c-text);
  font-size: 12px;
  font-weight: 600;
}

.panel__count {
  color: var(--c-primary);
  font-size: 12px;
  font-weight: 700;
}

.empty {
  margin-top: 4px;
  color: var(--c-text-muted);
  font-size: 11.5px;
}

.list {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 8px;
  margin: 5px 0 0;
  padding: 0;
  list-style: none;
}

.list__item {
  padding: 1px 7px;
  background: #f3ece0;
  border-radius: 999px;
  font-size: 11.5px;
}
