
.card {
  width: 100%;
  max-width: 460px;
  margin: 0 auto;
  background: var(--c-surface);
  border: 1px solid var(--c-border);
  border-radius: 10px;
  color: var(--c-text);
  font-family: var(--font-body);
  font-size: 13px;
  line-height: 1.5;
  overflow: hidden;
}

.fold {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 7px 12px;
  background: var(--c-surface-raised);
  border: none;
  border-top: 1px dashed var(--c-border);
  color: var(--c-text);
  font: inherit;
  cursor: pointer;
  text-align: left;

  &:hover {
    background: #f3ece0;
  }
}

.fold__state {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-weight: 600;
}

.fold__dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--c-text-muted);

  &.is-hot {
    background: var(--c-accent);
    box-shadow: 0 0 0 3px rgb(180 72 92 / 18%);
  }
}

.fold__top {
  flex: 1;
  color: var(--c-text-muted);
  font-size: 12px;
}

.fold__chev {
  color: var(--c-primary);
  font-size: 12px;
}

.body {
  padding: 10px 12px 12px;
  border-top: 1px solid var(--c-border);
}
